export type Provider = "BITFINEX" | "BINANCE" | "CRYPTOCAP";
export type Timeframe = "1m" | "5m" | "15m" | "1h" | "4h" | "1D" | "1W";
export type ConnectionStatus = "connecting" | "live" | "reconnecting" | "degraded" | "offline";

export interface Instrument {
  provider: Provider;
  symbol: string;
  label: string;
  base: string;
  quote: string;
}

export interface ChartPanel {
  id: string;
  provider: Provider;
  symbol: string;
  timeframe: Timeframe;
  position: number;
  span: number;
}

export interface Dashboard {
  id: string;
  name: string;
  columns: number;
  panels: ChartPanel[];
  updatedAt: string;
}

export interface MarketSnapshot {
  symbol: string;
  price: number | null;
  change24h: number | null;
  volume24h: number | null;
  timestamp: number;
  stale: boolean;
  sourceStatus: "live" | "stale" | "unavailable";
}

export type ClientStreamMessage =
  | { type: "subscribe"; symbols: string[] }
  | { type: "ping" };

export type ServerStreamMessage =
  | { type: "snapshot" | "tick"; data: MarketSnapshot[] }
  | { type: "status"; status: ConnectionStatus; message?: string }
  | { type: "pong" };

export const TIMEFRAMES: Timeframe[] = ["1m", "5m", "15m", "1h", "4h", "1D", "1W"];

export const INSTRUMENTS: Instrument[] = [
  { provider: "BITFINEX", symbol: "BITFINEX:BTCUSD", label: "Bitcoin / US Dollar", base: "BTC", quote: "USD" },
  { provider: "BITFINEX", symbol: "BITFINEX:ETHUSD", label: "Ethereum / US Dollar", base: "ETH", quote: "USD" },
  { provider: "BITFINEX", symbol: "BITFINEX:LTCUSD", label: "Litecoin / US Dollar", base: "LTC", quote: "USD" },
  { provider: "BINANCE", symbol: "BINANCE:SOLUSDT", label: "Solana / Tether", base: "SOL", quote: "USDT" },
  { provider: "BINANCE", symbol: "BINANCE:XRPUSDT", label: "XRP / Tether", base: "XRP", quote: "USDT" },
  { provider: "BINANCE", symbol: "BINANCE:DOGEUSDT", label: "Dogecoin / Tether", base: "DOGE", quote: "USDT" },
  { provider: "CRYPTOCAP", symbol: "CRYPTOCAP:TOTAL", label: "Total Crypto Market Cap", base: "TOTAL", quote: "USD" },
  { provider: "CRYPTOCAP", symbol: "CRYPTOCAP:BTC.D", label: "Bitcoin Dominance", base: "BTC.D", quote: "%" },
];

import { sql } from "drizzle-orm";
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const dashboards = sqliteTable("dashboards", {
  id: text("id").primaryKey(),
  ownerHash: text("owner_hash").notNull().unique(),
  name: text("name").notNull().default("MY MARKET GRID"),
  columns: integer("columns").notNull().default(2),
  createdAt: text("created_at").notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: text("updated_at").notNull().default(sql`CURRENT_TIMESTAMP`),
});

export const chartPanels = sqliteTable("chart_panels", {
  id: text("id").primaryKey(),
  dashboardId: text("dashboard_id").notNull().references(() => dashboards.id, { onDelete: "cascade" }),
  provider: text("provider").notNull(),
  symbol: text("symbol").notNull(),
  timeframe: text("timeframe").notNull().default("1h"),
  position: integer("position").notNull(),
  span: integer("span").notNull().default(1),
  createdAt: text("created_at").notNull().default(sql`CURRENT_TIMESTAMP`),
  updatedAt: text("updated_at").notNull().default(sql`CURRENT_TIMESTAMP`),
}, (table) => [index("chart_panels_dashboard_position_idx").on(table.dashboardId, table.position)]);

import type { ChartPanel, Dashboard, Instrument, MarketSnapshot, Provider, Timeframe } from "./types";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, init);
  if (!response.ok) {
    const body = await response.json().catch(() => ({ error: "Permintaan gagal." })) as { error?: string };
    throw new Error(body.error ?? `Permintaan gagal (${response.status}).`);
  }
  return response.json() as Promise<T>;
}

const jsonInit = (method: string, body: unknown): RequestInit => ({
  method,
  headers: { "content-type": "application/json" },
  body: JSON.stringify(body),
});

export const api = {
  dashboard: () => request<Dashboard>("/api/dashboard"),
  instruments: (query: string, signal?: AbortSignal) =>
    request<Instrument[]>(`/api/instruments?q=${encodeURIComponent(query)}`, { signal }),
  snapshots: (symbols: string[]) =>
    request<MarketSnapshot[]>(`/api/market/snapshot?symbols=${encodeURIComponent(symbols.join(","))}`),
  addPanel: (provider: Provider, symbol: string, timeframe: Timeframe) =>
    request<ChartPanel>("/api/dashboard/panels", jsonInit("POST", { provider, symbol, timeframe })),
  updatePanel: (id: string, changes: Partial<Pick<ChartPanel, "provider" | "symbol" | "timeframe" | "span">>) =>
    request<ChartPanel>(`/api/dashboard/panels/${id}`, jsonInit("PATCH", changes)),
  removePanel: (id: string) => request<{ ok: true }>(`/api/dashboard/panels/${id}`, { method: "DELETE" }),
  saveLayout: (columns: number, panelIds: string[]) =>
    request<{ ok: true }>("/api/dashboard/layout", jsonInit("PUT", { columns, panelIds })),
};

import { and, asc, eq } from "drizzle-orm";
import { getDb } from "../src/db/client";
import { chartPanels, dashboards } from "../src/db/schema";
import { INSTRUMENTS, TIMEFRAMES, type ChartPanel, type Dashboard, type MarketSnapshot, type Provider, type Timeframe } from "../src/lib/types";

interface Env {
  DB: D1Database;
  MARKET_HUB: DurableObjectNamespace;
  GLOBAL_METRICS_API_URL?: string;
  GLOBAL_METRICS_API_KEY?: string;
}

const DEFAULTS = INSTRUMENTS.map((instrument) => ({ ...instrument, timeframe: "1h" as Timeframe }));
const MAX_PANELS = 16;
const json = (data: unknown, status = 200, headers?: HeadersInit) => Response.json(data, { status, headers });
const error = (message: string, status = 400) => json({ error: message }, status);
const validInstrument = (provider: unknown, symbol: unknown) => INSTRUMENTS.find((item) => item.provider === provider && item.symbol === symbol);
const validTimeframe = (value: unknown): value is Timeframe => typeof value === "string" && TIMEFRAMES.includes(value as Timeframe);

async function owner(request: Request): Promise<{ token: string; hash: string; cookie?: string }> {
  const found = request.headers.get("cookie")?.match(/(?:^|;\s*)dmg_owner=([^;]+)/)?.[1];
  const token = found ?? crypto.randomUUID().replaceAll("-", "") + crypto.randomUUID().replaceAll("-", "");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  const hash = [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
  return { token, hash, cookie: found ? undefined : `dmg_owner=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000` };
}

async function findDashboard(env: Env, ownerHash: string) {
  const db = getDb(env);
  return (await db.select().from(dashboards).where(eq(dashboards.ownerHash, ownerHash)).limit(1))[0];
}

async function ensureDashboard(env: Env, ownerHash: string): Promise<typeof dashboards.$inferSelect> {
  const existing = await findDashboard(env, ownerHash);
  if (existing) return existing;
  const dashboardId = crypto.randomUUID();
  await env.DB.batch([
    env.DB.prepare("INSERT INTO dashboards (id, owner_hash, name, columns) VALUES (?, ?, ?, ?)").bind(dashboardId, ownerHash, "MY MARKET GRID", 2),
    ...DEFAULTS.map((item, index) => env.DB.prepare("INSERT INTO chart_panels (id, dashboard_id, provider, symbol, timeframe, position, span) VALUES (?, ?, ?, ?, ?, ?, 1)").bind(crypto.randomUUID(), dashboardId, item.provider, item.symbol, item.timeframe, index)),
  ]);
  const created = await findDashboard(env, ownerHash);
  if (!created) throw new Error("Dashboard gagal dibuat.");
  return created;
}

async function fullDashboard(env: Env, ownerHash: string): Promise<Dashboard> {
  const dashboard = await ensureDashboard(env, ownerHash);
  const rows = await getDb(env).select().from(chartPanels).where(eq(chartPanels.dashboardId, dashboard.id)).orderBy(asc(chartPanels.position));
  return {
    id: dashboard.id,
    name: dashboard.name,
    columns: dashboard.columns,
    updatedAt: dashboard.updatedAt,
    panels: rows.map((row) => ({ id: row.id, provider: row.provider as Provider, symbol: row.symbol, timeframe: row.timeframe as Timeframe, position: row.position, span: row.span })),
  };
}

async function parseBody(request: Request): Promise<Record<string, unknown> | null> {
  if (!request.headers.get("content-type")?.includes("application/json")) return null;
  try { return await request.json() as Record<string, unknown>; } catch { return null; }
}

function panelResponse(row: typeof chartPanels.$inferSelect): ChartPanel {
  return { id: row.id, provider: row.provider as Provider, symbol: row.symbol, timeframe: row.timeframe as Timeframe, position: row.position, span: row.span };
}

async function marketSnapshot(symbol: string, env?: Env): Promise<MarketSnapshot> {
  const unavailable = (): MarketSnapshot => ({ symbol, price: null, change24h: null, volume24h: null, timestamp: Date.now(), stale: true, sourceStatus: "unavailable" });
  try {
    if (symbol.startsWith("BINANCE:")) {
      const pair = symbol.split(":")[1];
      const response = await fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${pair}`, { cf: { cacheTtl: 0 } });
      if (!response.ok) return unavailable();
      const data = await response.json() as { lastPrice: string; priceChangePercent: string; quoteVolume: string; closeTime: number };
      return { symbol, price: Number(data.lastPrice), change24h: Number(data.priceChangePercent), volume24h: Number(data.quoteVolume), timestamp: data.closeTime, stale: Date.now() - data.closeTime > 60_000, sourceStatus: "live" };
    }
    if (symbol.startsWith("BITFINEX:")) {
      const pair = symbol.split(":")[1];
      const response = await fetch(`https://api-pub.bitfinex.com/v2/ticker/t${pair}`, { cf: { cacheTtl: 0 } });
      if (!response.ok) return unavailable();
      const data = await response.json() as number[];
      return { symbol, price: data[6] ?? null, change24h: (data[5] ?? 0) * 100, volume24h: data[7] ?? null, timestamp: Date.now(), stale: false, sourceStatus: "live" };
    }
    if (env?.GLOBAL_METRICS_API_URL) {
      const response = await fetch(`${env.GLOBAL_METRICS_API_URL}?symbol=${encodeURIComponent(symbol)}`, { headers: env.GLOBAL_METRICS_API_KEY ? { authorization: `Bearer ${env.GLOBAL_METRICS_API_KEY}` } : undefined });
      if (response.ok) {
        const data = await response.json() as { price: number; change24h?: number; timestamp?: number };
        return { symbol, price: data.price, change24h: data.change24h ?? null, volume24h: null, timestamp: data.timestamp ?? Date.now(), stale: false, sourceStatus: "live" };
      }
    }
    return unavailable();
  } catch { return unavailable(); }
}

export class MarketHub implements DurableObject {
  constructor(private readonly state: DurableObjectState, private readonly env: Env) {}

  async fetch(request: Request): Promise<Response> {
    if (request.headers.get("upgrade") !== "websocket") return error("WebSocket diperlukan.", 426);
    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    this.state.acceptWebSocket(server);
    server.serializeAttachment({ symbols: [] });
    server.send(JSON.stringify({ type: "status", status: "connecting" }));
    await this.state.storage.setAlarm(Date.now() + 250);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(socket: WebSocket, message: string | ArrayBuffer) {
    if (typeof message !== "string" || message.length > 4096) return socket.close(1009, "Pesan terlalu besar");
    try {
      const parsed = JSON.parse(message) as { type?: string; symbols?: unknown };
      if (parsed.type === "ping") return socket.send(JSON.stringify({ type: "pong" }));
      if (parsed.type === "subscribe" && Array.isArray(parsed.symbols)) {
        const symbols = [...new Set(parsed.symbols.filter((value): value is string => typeof value === "string" && INSTRUMENTS.some((item) => item.symbol === value)))].slice(0, MAX_PANELS);
        socket.serializeAttachment({ symbols });
        const data = await Promise.all(symbols.map((symbol) => marketSnapshot(symbol, this.env)));
        socket.send(JSON.stringify({ type: "snapshot", data }));
        socket.send(JSON.stringify({ type: "status", status: data.some((item) => item.sourceStatus === "live") ? "live" : "degraded" }));
        await this.state.storage.setAlarm(Date.now() + 8_000);
      }
    } catch { socket.send(JSON.stringify({ type: "status", status: "degraded", message: "Pesan stream tidak valid." })); }
  }

  async alarm() {
    const sockets = this.state.getWebSockets();
    if (!sockets.length) return;
    const all = new Set<string>();
    for (const socket of sockets) {
      const attachment = socket.deserializeAttachment() as { symbols?: string[] } | null;
      attachment?.symbols?.forEach((symbol) => all.add(symbol));
    }
    const snapshots = await Promise.all([...all].map((symbol) => marketSnapshot(symbol, this.env)));
    for (const socket of sockets) {
      const attachment = socket.deserializeAttachment() as { symbols?: string[] } | null;
      const subscribed = new Set(attachment?.symbols ?? []);
      socket.send(JSON.stringify({ type: "tick", data: snapshots.filter((item) => subscribed.has(item.symbol)) }));
    }
    await this.state.storage.setAlarm(Date.now() + 8_000);
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const securityHeaders = { "cache-control": "no-store", "x-content-type-options": "nosniff" };
    if (url.pathname === "/api/health") {
      try { await env.DB.prepare("SELECT 1").first(); return json({ ok: true, database: "available", feed: "available" }, 200, securityHeaders); }
      catch { return json({ ok: false, database: "unavailable", feed: "available" }, 503, securityHeaders); }
    }
    if (url.pathname === "/api/instruments" && request.method === "GET") {
      const query = (url.searchParams.get("q") ?? "").trim().toLowerCase().slice(0, 60);
      const results = INSTRUMENTS.filter((item) => `${item.symbol} ${item.label} ${item.base} ${item.quote}`.toLowerCase().includes(query)).slice(0, 12);
      return json(results, 200, securityHeaders);
    }
    if (url.pathname === "/api/market/snapshot" && request.method === "GET") {
      const symbols = [...new Set((url.searchParams.get("symbols") ?? "").split(","))].filter((symbol) => INSTRUMENTS.some((item) => item.symbol === symbol)).slice(0, MAX_PANELS);
      return json(await Promise.all(symbols.map((symbol) => marketSnapshot(symbol, env))), 200, securityHeaders);
    }
    if (url.pathname === "/api/market/stream") {
      const id = env.MARKET_HUB.idFromName("global-market-hub");
      return env.MARKET_HUB.get(id).fetch(request);
    }
    if (!url.pathname.startsWith("/api/dashboard")) return error("Endpoint tidak ditemukan.", 404);

    const identity = await owner(request);
    const headers = new Headers(securityHeaders);
    if (identity.cookie) headers.set("set-cookie", identity.cookie);
    try {
      if (url.pathname === "/api/dashboard" && request.method === "GET") return json(await fullDashboard(env, identity.hash), 200, headers);
      const dashboard = await ensureDashboard(env, identity.hash);
      const db = getDb(env);
      if (url.pathname === "/api/dashboard/layout" && request.method === "PUT") {
        const body = await parseBody(request);
        const columns = body?.columns;
        const panelIds = body?.panelIds;
        const owned = await db.select({ id: chartPanels.id }).from(chartPanels).where(eq(chartPanels.dashboardId, dashboard.id));
        if (!Number.isInteger(columns) || Number(columns) < 1 || Number(columns) > 4 || !Array.isArray(panelIds) || panelIds.length !== owned.length || new Set(panelIds).size !== panelIds.length || panelIds.some((id) => typeof id !== "string" || !owned.some((row) => row.id === id))) return error("Susunan dashboard tidak valid.", 422);
        await env.DB.batch([
          env.DB.prepare("UPDATE dashboards SET columns = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?").bind(columns, dashboard.id),
          ...panelIds.map((id, index) => env.DB.prepare("UPDATE chart_panels SET position = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND dashboard_id = ?").bind(index, id, dashboard.id)),
        ]);
        return json({ ok: true }, 200, headers);
      }
      if (url.pathname === "/api/dashboard/panels" && request.method === "POST") {
        const body = await parseBody(request);
        const instrument = validInstrument(body?.provider, body?.symbol);
        if (!instrument || !validTimeframe(body?.timeframe)) return error("Instrumen atau timeframe tidak valid.", 422);
        const rows = await db.select().from(chartPanels).where(eq(chartPanels.dashboardId, dashboard.id));
        if (rows.length >= MAX_PANELS) return error("Maksimum 16 chart.", 429);
        const row = { id: crypto.randomUUID(), dashboardId: dashboard.id, provider: instrument.provider, symbol: instrument.symbol, timeframe: body.timeframe, position: rows.length, span: 1 };
        await db.insert(chartPanels).values(row);
        return json(panelResponse({ ...row, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }), 201, headers);
      }
      const match = url.pathname.match(/^\/api\/dashboard\/panels\/([\w-]+)$/);
      if (match) {
        const panelId = match[1];
        const current = (await db.select().from(chartPanels).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id))).limit(1))[0];
        if (!current) return error("Panel tidak ditemukan.", 404);
        if (request.method === "DELETE") {
          await db.delete(chartPanels).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id)));
          return json({ ok: true }, 200, headers);
        }
        if (request.method === "PATCH") {
          const body = await parseBody(request);
          const provider = body?.provider ?? current.provider;
          const symbol = body?.symbol ?? current.symbol;
          const timeframe = body?.timeframe ?? current.timeframe;
          const span = body?.span ?? current.span;
          if (!validInstrument(provider, symbol) || !validTimeframe(timeframe) || !Number.isInteger(span) || Number(span) < 1 || Number(span) > 2) return error("Perubahan panel tidak valid.", 422);
          await db.update(chartPanels).set({ provider: String(provider), symbol: String(symbol), timeframe, span: Number(span), updatedAt: new Date().toISOString() }).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id)));
          const updated = (await db.select().from(chartPanels).where(eq(chartPanels.id, panelId)).limit(1))[0];
          return json(panelResponse(updated), 200, headers);
        }
      }
      return error("Endpoint tidak ditemukan.", 404);
    } catch (cause) {
      console.error("Dashboard request failed", cause);
      return error("Layanan dashboard sedang bermasalah. Coba lagi.", 500);
    }
  },
} satisfies ExportedHandler<Env>;

import { StrictMode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import { Activity, AlertTriangle, ArrowDown, ArrowUp, BarChart3, Check, ChevronDown, GripVertical, LayoutGrid, LoaderCircle, Plus, RefreshCw, Search, Settings2, Trash2, X } from "lucide-react";
import { api } from "./lib/api";
import { INSTRUMENTS, TIMEFRAMES, type ChartPanel as Panel, type ConnectionStatus, type Dashboard, type Instrument, type MarketSnapshot, type Timeframe } from "./lib/types";
import "./styles.css";

const intervalMap: Record<Timeframe, string> = { "1m": "1", "5m": "5", "15m": "15", "1h": "60", "4h": "240", "1D": "D", "1W": "W" };
const money = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 2 });

function TradingViewChart({ panel, retryKey }: { panel: Panel; retryKey: number }) {
  const src = `https://s.tradingview.com/widgetembed/?symbol=${encodeURIComponent(panel.symbol)}&interval=${intervalMap[panel.timeframe]}&theme=dark&style=1&locale=id&hide_side_toolbar=1&allow_symbol_change=0&save_image=0&calendar=0&utm_source=defi-market-grid`;
  return <iframe key={`${panel.symbol}-${panel.timeframe}-${retryKey}`} className="chart-frame" title={`Chart ${panel.symbol}`} src={src} loading="lazy" allowFullScreen />;
}

function ConnectionBadge({ status, onRetry }: { status: ConnectionStatus; onRetry: () => void }) {
  const labels: Record<ConnectionStatus, string> = { connecting: "MENGHUBUNGKAN", live: "LIVE", reconnecting: "MENYAMBUNG ULANG", degraded: "TERBATAS", offline: "OFFLINE" };
  return <button className={`connection ${status}`} onClick={onRetry} title="Klik untuk sambungkan ulang"><span className="pulse" />{labels[status]}</button>;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const modal = ref.current;
    modal?.querySelector<HTMLElement>("input,button,select")?.focus();
    const key = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
      if (event.key === "Tab" && modal) {
        const items = [...modal.querySelectorAll<HTMLElement>("button,input,select,[tabindex]:not([tabindex='-1'])")];
        if (!items.length) return;
        const first = items[0], last = items[items.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener("keydown", key);
    return () => { document.removeEventListener("keydown", key); previous?.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" role="presentation" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-head"><div><span className="eyebrow">GRID MODULE</span><h2 id="modal-title">{title}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Tutup dialog"><X /></button></div>{children}</div></div>;
}

function InstrumentSearch({ onClose, onAdd, initial }: { onClose: () => void; onAdd: (instrument: Instrument, timeframe: Timeframe) => Promise<void>; initial?: Panel }) {
  const [query, setQuery] = useState(initial?.symbol.split(":")[1] ?? "");
  const [results, setResults] = useState<Instrument[]>(INSTRUMENTS);
  const [selected, setSelected] = useState<Instrument | null>(initial ? INSTRUMENTS.find((i) => i.symbol === initial.symbol) ?? null : null);
  const [timeframe, setTimeframe] = useState<Timeframe>(initial?.timeframe ?? "1h");
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState("");
  useEffect(() => {
    const controller = new AbortController();
    const timer = window.setTimeout(() => api.instruments(query, controller.signal).then(setResults).catch((error: Error) => error.name !== "AbortError" && setFailed(error.message)), 220);
    return () => { clearTimeout(timer); controller.abort(); };
  }, [query]);
  const submit = async () => {
    if (!selected) return;
    setBusy(true); setFailed("");
    try { await onAdd(selected, timeframe); onClose(); } catch (error) { setFailed(error instanceof Error ? error.message : "Gagal menyimpan."); setBusy(false); }
  };
  return <Modal title={initial ? "ATUR CHART" : "TAMBAH INSTRUMEN"} onClose={onClose}>
    <label className="field-label" htmlFor="instrument-query">Cari exchange, pair, atau simbol</label>
    <div className="search-box"><Search /><input id="instrument-query" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Contoh: BTC, Binance, ETHUSD" /></div>
    <div className="instrument-list" role="listbox" aria-label="Hasil instrumen">
      {results.map((item) => <button key={item.symbol} role="option" aria-selected={selected?.symbol === item.symbol} className={`instrument-row ${selected?.symbol === item.symbol ? "selected" : ""}`} onClick={() => setSelected(item)}><span className={`provider-mark ${item.provider.toLowerCase()}`}>{item.base.slice(0, 1)}</span><span><strong>{item.base}<i> / {item.quote}</i></strong><small>{item.provider} · {item.label}</small></span>{selected?.symbol === item.symbol && <Check />}</button>)}
      {!results.length && <div className="no-results"><Search /><strong>Tidak ditemukan</strong><span>Coba kata kunci atau exchange lain.</span></div>}
    </div>
    <label className="field-label" htmlFor="add-timeframe">Timeframe awal</label>
    <select id="add-timeframe" className="select-wide" value={timeframe} onChange={(e) => setTimeframe(e.target.value as Timeframe)}>{TIMEFRAMES.map((tf) => <option key={tf}>{tf}</option>)}</select>
    {failed && <p className="form-error"><AlertTriangle />{failed}</p>}
    <div className="modal-actions"><button className="btn ghost" onClick={onClose}>BATAL</button><button className="btn primary" disabled={!selected || busy} onClick={submit}>{busy ? <LoaderCircle className="spin" /> : <Plus />}{initial ? "SIMPAN" : "TAMBAH CHART"}</button></div>
  </Modal>;
}

function ChartPanel({ panel, snapshot, onTimeframe, onRemove, onMove, onEdit, draggable, onDragStart, onDrop }: { panel: Panel; snapshot?: MarketSnapshot; onTimeframe: (tf: Timeframe) => void; onRemove: () => void; onMove: (direction: -1 | 1) => void; onEdit: () => void; draggable: boolean; onDragStart: () => void; onDrop: () => void }) {
  const [retryKey, setRetryKey] = useState(0);
  const pair = panel.symbol.split(":")[1];
  const change = snapshot?.change24h;
  return <article className="market-panel" draggable={draggable} onDragStart={onDragStart} onDragOver={(e) => e.preventDefault()} onDrop={onDrop}>
    <header className="panel-head">
      <button className="drag-handle" aria-label={`Seret ${panel.symbol}`} title="Seret untuk menyusun"><GripVertical /></button>
      <div className="asset-icon">{pair?.slice(0, 1)}</div>
      <div className="asset-title"><span>{panel.provider}</span><h2>{pair}</h2></div>
      <div className="price-block"><strong>{snapshot?.price == null ? "—" : panel.symbol === "CRYPTOCAP:BTC.D" ? `${snapshot.price.toFixed(2)}%` : `$${money.format(snapshot.price)}`}</strong><span className={change == null ? "muted" : change >= 0 ? "positive" : "negative"}>{change == null ? "DATA TERTUNDA" : `${change >= 0 ? "+" : ""}${change.toFixed(2)}%`}</span></div>
      <div className="panel-actions"><button className="icon-btn" onClick={() => onMove(-1)} aria-label="Pindah ke atas"><ArrowUp /></button><button className="icon-btn" onClick={() => onMove(1)} aria-label="Pindah ke bawah"><ArrowDown /></button><button className="icon-btn" onClick={onEdit} aria-label={`Atur ${panel.symbol}`}><Settings2 /></button><button className="icon-btn danger" onClick={onRemove} aria-label={`Hapus ${panel.symbol}`}><Trash2 /></button></div>
    </header>
    <div className="panel-meta"><div className="timeframes" aria-label={`Timeframe ${panel.symbol}`}>{TIMEFRAMES.map((tf) => <button key={tf} className={panel.timeframe === tf ? "active" : ""} onClick={() => onTimeframe(tf)}>{tf}</button>)}</div><span className="volume">VOL 24H&nbsp; {snapshot?.volume24h == null ? "—" : compact.format(snapshot.volume24h)}</span></div>
    <div className="chart-wrap"><TradingViewChart panel={panel} retryKey={retryKey} />{snapshot?.sourceStatus === "unavailable" && <div className="data-warning"><AlertTriangle />Feed harga belum tersedia <button onClick={() => setRetryKey((v) => v + 1)}><RefreshCw /> Coba chart</button></div>}</div>
  </article>;
}

function App() {
  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
  const [snapshots, setSnapshots] = useState<Record<string, MarketSnapshot>>({});
  const [status, setStatus] = useState<ConnectionStatus>("connecting");
  const [loadingError, setLoadingError] = useState("");
  const [modal, setModal] = useState<"add" | "edit" | "delete" | null>(null);
  const [activePanel, setActivePanel] = useState<Panel | null>(null);
  const [saving, setSaving] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
  const [streamKey, setStreamKey] = useState(0);
  const [dragged, setDragged] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState("");

  const load = useCallback(() => { setLoadingError(""); api.dashboard().then(setDashboard).catch((error: Error) => setLoadingError(error.message)); }, []);
  useEffect(load, [load]);
  const symbols = useMemo(() => [...new Set(dashboard?.panels.map((p) => p.symbol) ?? [])], [dashboard]);
  useEffect(() => {
    if (!symbols.length) { setStatus("offline"); return; }
    let closed = false, attempts = 0, socket: WebSocket | null = null, timer = 0;
    const connect = () => {
      if (closed) return;
      setStatus(attempts ? "reconnecting" : "connecting");
      socket = new WebSocket(`${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/api/market/stream`);
      socket.onopen = () => { attempts = 0; socket?.send(JSON.stringify({ type: "subscribe", symbols })); };
      socket.onmessage = (event) => {
        const message = JSON.parse(String(event.data)) as { type: string; status?: ConnectionStatus; data?: MarketSnapshot[] };
        if (message.status) setStatus(message.status);
        if (message.data) { setSnapshots((current) => ({ ...current, ...Object.fromEntries(message.data!.map((item) => [item.symbol, item])) })); setLastUpdate(Date.now()); }
      };
      socket.onerror = () => setStatus("degraded");
      socket.onclose = () => { if (!closed) { attempts++; setStatus("reconnecting"); timer = window.setTimeout(connect, Math.min(30_000, 1000 * 2 ** attempts) + Math.random() * 500); } };
    };
    api.snapshots(symbols).then((data) => setSnapshots(Object.fromEntries(data.map((item) => [item.symbol, item])))).catch(() => undefined);
    connect();
    const heartbeat = window.setInterval(() => socket?.readyState === WebSocket.OPEN && socket.send(JSON.stringify({ type: "ping" })), 20_000);
    return () => { closed = true; clearTimeout(timer); clearInterval(heartbeat); socket?.close(); };
  }, [symbols, streamKey]);

  const saveLayout = async (panels: Panel[], columns = dashboard?.columns ?? 2) => {
    if (!dashboard) return;
    const old = dashboard;
    const positioned = panels.map((panel, position) => ({ ...panel, position }));
    setDashboard({ ...dashboard, panels: positioned, columns }); setSaving(true);
    try { await api.saveLayout(columns, positioned.map((p) => p.id)); }
    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Gagal menyimpan susunan."); }
    finally { setSaving(false); }
  };
  const move = (id: string, direction: -1 | 1) => {
    if (!dashboard) return;
    const index = dashboard.panels.findIndex((p) => p.id === id), target = index + direction;
    if (target < 0 || target >= dashboard.panels.length) return;
    const next = [...dashboard.panels]; [next[index], next[target]] = [next[target], next[index]];
    setAnnouncement(`${dashboard.panels[index].symbol} dipindahkan ke posisi ${target + 1}.`); void saveLayout(next);
  };
  const mutatePanel = async (panel: Panel, changes: Partial<Panel>) => {
    if (!dashboard) return;
    const old = dashboard; setDashboard({ ...dashboard, panels: dashboard.panels.map((p) => p.id === panel.id ? { ...p, ...changes } : p) }); setSaving(true);
    try { const updated = await api.updatePanel(panel.id, changes); setDashboard((current) => current ? { ...current, panels: current.panels.map((p) => p.id === panel.id ? updated : p) } : current); }
    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Perubahan gagal."); throw error; }
    finally { setSaving(false); }
  };
  const remove = async () => {
    if (!dashboard || !activePanel) return; const old = dashboard; setModal(null); setDashboard({ ...dashboard, panels: dashboard.panels.filter((p) => p.id !== activePanel.id) }); setSaving(true);
    try { await api.removePanel(activePanel.id); setAnnouncement(`${activePanel.symbol} dihapus.`); }
    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Gagal menghapus."); }
    finally { setSaving(false); setActivePanel(null); }
  };

  if (loadingError) return <main className="center-state"><AlertTriangle /><h1>DASHBOARD TIDAK TERJANGKAU</h1><p>{loadingError}</p><button className="btn primary" onClick={load}><RefreshCw /> COBA LAGI</button></main>;
  if (!dashboard) return <main className="center-state"><LoaderCircle className="spin" /><h1>MENYUSUN MARKET GRID</h1><p>Memuat panel dan menghubungkan feed pasar…</p></main>;

  return <div className="app-shell">
    <div className="ticker-strip"><span>DEFI MARKET GRID // LIVE INTELLIGENCE</span><span>BTC · ETH · SOL · XRP · DOGE · TOTAL MARKET</span><span>UTC {new Date().toISOString().slice(11, 19)}</span></div>
    <header className="topbar"><a className="brand" href="#top" aria-label="DeFi Market Grid"><span className="brand-mark"><BarChart3 /></span><span><strong>DEFI</strong> MARKET GRID<small>REAL-TIME CRYPTO MONITOR</small></span></a><div className="top-actions"><ConnectionBadge status={status} onRetry={() => setStreamKey((v) => v + 1)} /><span className="updated">UPDATE TERAKHIR<strong>{lastUpdate ? new Date(lastUpdate).toLocaleTimeString("id-ID") : "—"}</strong></span><button className="btn primary" onClick={() => setModal("add")}><Plus /> TAMBAH CHART</button></div></header>
    <main id="top"><section className="workspace-head"><div><span className="eyebrow">WORKSPACE / 01</span><h1>{dashboard.name}</h1><p>{dashboard.panels.length} MODUL AKTIF · MARKET DATA TANPA REFRESH</p></div><div className="layout-control"><label><LayoutGrid /> KOLOM</label>{[1, 2, 3, 4].map((count) => <button key={count} aria-label={`${count} kolom`} className={dashboard.columns === count ? "active" : ""} onClick={() => void saveLayout(dashboard.panels, count)}>{count}</button>)}<span className={saving ? "saving active" : "saving"}>{saving ? "MENYIMPAN…" : "TERSIMPAN"}</span></div></section>
      {dashboard.panels.length ? <section className="market-grid" style={{ "--columns": dashboard.columns } as React.CSSProperties}>{dashboard.panels.map((panel) => <ChartPanel key={panel.id} panel={panel} snapshot={snapshots[panel.symbol]} draggable onDragStart={() => setDragged(panel.id)} onDrop={() => { if (!dragged || dragged === panel.id) return; const next = [...dashboard.panels]; const from = next.findIndex((p) => p.id === dragged), to = next.findIndex((p) => p.id === panel.id); const [item] = next.splice(from, 1); next.splice(to, 0, item); setDragged(null); void saveLayout(next); }} onMove={(d) => move(panel.id, d)} onTimeframe={(tf) => void mutatePanel(panel, { timeframe: tf })} onEdit={() => { setActivePanel(panel); setModal("edit"); }} onRemove={() => { setActivePanel(panel); setModal("delete"); }} />)}</section> : <section className="empty-state"><Activity /><span className="eyebrow">GRID KOSONG</span><h2>MULAI PANTAU PASAR</h2><p>Tambahkan instrumen pertama untuk membangun workspace Anda.</p><button className="btn primary" onClick={() => setModal("add")}><Plus /> TAMBAH CHART</button></section>}
    </main>
    <footer><div><strong>DATA PIPELINE</strong><span><i className="dot live" /> BINANCE PUBLIC API</span><span><i className="dot live" /> BITFINEX PUBLIC API</span><span><i className="dot limited" /> GLOBAL METRICS*</span></div><p>Chart oleh <a href="https://www.tradingview.com/" target="_blank" rel="noreferrer">TradingView</a>. Data oleh <a href="https://www.binance.com/en/terms" target="_blank" rel="noreferrer">Binance</a> dan <a href="https://www.bitfinex.com/legal/" target="_blank" rel="noreferrer">Bitfinex</a>. Data hanya untuk informasi, bukan nasihat finansial.</p></footer>
    <p className="sr-only" aria-live="polite">{announcement}</p>
    {modal === "add" && <InstrumentSearch onClose={() => setModal(null)} onAdd={async (instrument, timeframe) => { const added = await api.addPanel(instrument.provider, instrument.symbol, timeframe); setDashboard((current) => current ? { ...current, panels: [...current.panels, added] } : current); setAnnouncement(`${instrument.symbol} ditambahkan.`); }} />}
    {modal === "edit" && activePanel && <InstrumentSearch initial={activePanel} onClose={() => setModal(null)} onAdd={async (instrument, timeframe) => mutatePanel(activePanel, { provider: instrument.provider, symbol: instrument.symbol, timeframe })} />}
    {modal === "delete" && activePanel && <Modal title="HAPUS CHART?"><div className="confirm-copy"><div className="asset-icon large">{activePanel.symbol.split(":")[1]?.slice(0, 1)}</div><p><strong>{activePanel.symbol}</strong> akan dihapus dari grid. Tindakan ini tidak dapat dibatalkan.</p></div><div className="modal-actions"><button className="btn ghost" onClick={() => setModal(null)}>BATAL</button><button className="btn destructive" onClick={() => void remove()}><Trash2 /> HAPUS</button></div></Modal>}
  </div>;
}

createRoot(document.getElementById("root") as HTMLElement).render(<StrictMode><App /></StrictMode>);

