ar(--panel);box-shadow:6px 6px 0 #030405;transition:border-color .18s}.market-panel:hover{border-color:#666e79}.panel-head{min-height:70px;padding:10px 11px;display:flex;align-items:center;border-bottom:1px solid var(--line)}.drag-handle,.icon-btn{width:36px;height:36px;display:grid;place-items:center;border:0;background:transparent;color:var(--muted);cursor:pointer}.drag-handle{cursor:grab}.drag-handle svg,.icon-btn svg{width:16px}.icon-btn:hover{background:#242931;color:white}.icon-btn.danger:hover{color:var(--red)}.asset-icon{flex:none;width:36px;height:36px;display:grid;place-items:center;margin-right:10px;border:1px solid #565d66;background:#20252d;color:var(--lime);font:950 16px ui-monospace,monospace;transform:rotate(-3deg)}.asset-icon.large{width:54px;height:54px;font-size:24px}.asset-title{min-width:92px}.asset-title span{color:var(--muted);font:800 8px ui-monospace,monospace;letter-spacing:.12em}.asset-title h2{margin:2px 0 0;font-size:16px;letter-spacing:-.03em}.price-block{margin-left:auto;text-align:right;padding:0 12px}.price-block strong{display:block;font:800 clamp(14px,1.5vw,20px) ui-monospace,monospace;white-space:nowrap}.price-block span{font:800 9px ui-monospace,monospace}.positive{color:var(--cyan)}.negative{color:var(--red)}.muted{color:var(--muted)}.panel-actions{gap:1px;border-left:1px solid var(--line);padding-left:7px}.panel-meta{min-height:43px;padding:5px 10px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.timeframes{display:flex;gap:2px}.timeframes button{height:28px;min-width:29px;padding:0 5px;border:0;background:transparent;color:var(--muted);font:800 9px ui-monospace,monospace;cursor:pointer}.timeframes button:hover{color:white}.timeframes button.active{color:#080a0a;background:var(--lime)}.volume{color:var(--muted);font:700 8px ui-monospace,monospace;white-space:nowrap}.chart-wrap{height:300px;position:relative;background:#0d1014}.chart-frame{width:100%;height:100%;border:0;display:block}.data-warning{position:absolute;left:10px;bottom:10px;padding:6px 8px;display:flex;align-items:center;gap:6px;background:#171a20e8;border:1px solid #59484a;color:#c1c4c9;font:700 8px ui-monospace,monospace}.data-warning svg{width:12px;color:#ff9b51}.data-warning button{display:flex;align-items:center;gap:4px;border:0;background:transparent;color:var(--lime);font-weight:800;cursor:pointer}.data-warning button svg{color:inherit}.empty-state,.center-state{min-height:55vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:2px dashed var(--line);padding:30px}.empty-state>svg,.center-state>svg{width:45px;height:45px;color:var(--lime);margin-bottom:14px}.empty-state p,.center-state p{color:var(--muted);margin:8px 0 22px}.center-state{border:0;min-height:100vh}footer{margin-top:40px;padding:24px 28px;border-top:2px solid var(--line);display:flex;justify-content:space-between;color:var(--muted);font:700 9px/1.8 ui-monospace,monospace}footer div{display:flex;gap:18px}footer div strong{color:white}footer a{color:var(--lime)}footer p{max-width:650px;margin:0;text-align:right}.dot{margin-right:4px}.modal-backdrop{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:20px;background:#030405d9;backdrop-filter:blur(5px)}.modal{width:min(570px,100%);max-height:90vh;overflow:auto;border:2px solid #6d747d;background:#111419;padding:22px;box-shadow:10px 10px 0 var(--purple)}.modal-head{display:flex;align-items:start;justify-content:space-between;margin-bottom:20px}.modal h2{font-size:27px}.field-label{display:block;margin:15px 0 7px;color:#b5bac2;font:800 9px ui-monospace,monospace;letter-spacing:.1em}.search-box{height:48px;display:flex;align-items:center;border:2px solid #555d67;background:#090b0e}.search-box:focus-within{border-color:var(--lime)}.search-box svg{width:17px;margin:0 12px;color:var(--muted)}.search-box input{width:100%;height:100%;border:0;outline:0;background:transparent;color:white}.instrument-list{max-height:300px;overflow:auto;margin:12px 0;border:1px solid var(--line)}.instrument-row{width:100%;min-height:62px;padding:8px 12px;display:flex;align-items:center;text-align:left;border:0;border-bottom:1px solid var(--line);background:#0d1014;cursor:pointer}.instrument-row:hover,.instrument-row.selected{background:#1b2026}.instrument-row.selected{box-shadow:inset 3px 0 var(--lime)}.instrument-row>svg{margin-left:auto;width:17px;color:var(--lime)}.provider-mark{width:34px;height:34px;display:grid;place-items:center;margin-right:11px;background:#20252c;color:var(--lime);font-weight:900}.provider-mark.binance{color:#f6c94c}.provider-mark.cryptocap{color:var(--purple)}.instrument-row strong{font:900 12px ui-monospace,monospace}.instrument-row strong i{color:var(--muted);font-style:normal}.instrument-row small{display:block;margin-top:4px;color:var(--muted);font:700 8px ui-monospace,monospace}.select-wide{width:100%;height:44px;padding:0 12px;border:2px solid var(--line);background:#0a0c0f;color:white}.modal-actions{justify-content:flex-end;margin-top:20px}.no-results{padding:35px;display:flex;flex-direction:column;align-items:center;gap:5px;color:var(--muted);font-size:12px}.no-results svg{width:25px}.form-error{display:flex;align-items:center;gap:6px;color:var(--red);font-size:12px}.form-error svg{width:15px}.confirm-copy{display:flex;align-items:center;gap:15px;color:var(--muted)}.confirm-copy strong{color:white}.spin{animation:spin 1s linear infinite}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}:focus-visible{outline:3px solid var(--lime);outline-offset:2px}@keyframes spin{to{transform:rotate(360deg)}}
