@media(max-width:700px){.ticker-strip span:nth-child(2),.ticker-strip span:nth-child(3){display:none}.ticker-strip{justify-content:center}.topbar{position:static;padding:12px 14px;align-items:flex-start}.brand{font-size:16px}.brand-mark{width:40px;height:40px}.top-actions{flex-wrap:wrap;justify-content:flex-end}.connection{height:36px}.top-actions .btn{width:100%}main{padding:18px 10px}.workspace-head{align-items:flex-start;gap:18px;flex-direction:column}.layout-control{width:100%}.layout-control label{margin-right:auto}.layout-control button:nth-of-type(n+3){display:none}.market-grid{grid-template-columns:1fr!important}.panel-head{flex-wrap:wrap}.drag-handle{display:none}.asset-title{min-width:80px}.price-block{padding-right:3px}.panel-actions{width:100%;justify-content:flex-end;margin-top:8px;padding-top:6px;border-left:0;border-top:1px solid var(--line)}.panel-actions .icon-btn:nth-child(-n+2){display:grid}.panel-meta{align-items:flex-start;gap:5px;flex-direction:column}.timeframes{width:100%;justify-content:space-between}.volume{padding:4px}.chart-wrap{height:280px}footer{flex-direction:column;gap:15px;padding:20px 14px}footer div{flex-wrap:wrap;gap:8px 14px}footer p{text-align:left}.modal-backdrop{padding:0;align-items:end}.modal{width:100%;max-height:94vh;border-bottom:0;padding:18px;box-shadow:0 -6px 0 var(--purple)}}
