 1	import { cloudflare } from "@cloudflare/vite-plugin";
 2	import tailwindcss from "@tailwindcss/vite";
 3	import react from "@vitejs/plugin-react";
 4	import { defineConfig } from "vite";
 5	
 6	export default defineConfig({
 7	  resolve: {
 8	    alias: {
 9	      "#": "/src",
10	    },
11	  },
12	  plugins: [react(), tailwindcss(), cloudflare()],
13	});
14

  1	import { StrictMode, useCallback, useEffect, useMemo, useRef, useState } from "react";
  2	import { createRoot } from "react-dom/client";
  3	import { Activity, AlertTriangle, ArrowDown, ArrowUp, BarChart3, Check, GripVertical, LayoutGrid, LoaderCircle, Plus, RefreshCw, Search, Settings2, Trash2, X } from "lucide-react";
  4	import { api } from "./lib/api";
  5	import { INSTRUMENTS, TIMEFRAMES, type ChartPanel as Panel, type ConnectionStatus, type Dashboard, type Instrument, type MarketSnapshot, type Timeframe } from "./lib/types";
  6	import "./styles.css";
  7	
  8	const intervalMap: Record<Timeframe, string> = { "1m": "1", "5m": "5", "15m": "15", "1h": "60", "4h": "240", "1D": "D", "1W": "W" };
  9	const money = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
 10	const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 2 });
 11	
 12	function TradingViewChart({ panel, retryKey }: { panel: Panel; retryKey: number }) {
 13	  const src = `https://s.tradingview.com/widgetembed/?symbol=${encodeURIComponent(panel.symbol)}&interval=${intervalMap[panel.timeframe]}&theme=dark&style=1&locale=id&hide_side_toolbar=1&allow_symbol_change=0&save_image=0&calendar=0&utm_source=defi-market-grid`;
 14	  return <iframe key={`${panel.symbol}-${panel.timeframe}-${retryKey}`} className="chart-frame" title={`Chart ${panel.symbol}`} src={src} loading="lazy" allowFullScreen />;
 15	}
 16	
 17	function ConnectionBadge({ status, onRetry }: { status: ConnectionStatus; onRetry: () => void }) {
 18	  const labels: Record<ConnectionStatus, string> = { connecting: "MENGHUBUNGKAN", live: "LIVE", reconnecting: "MENYAMBUNG ULANG", degraded: "TERBATAS", offline: "OFFLINE" };
 19	  return <button className={`connection ${status}`} onClick={onRetry} title="Klik untuk sambungkan ulang"><span className="pulse" />{labels[status]}</button>;
 20	}
 21	
 22	function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
 23	  const ref = useRef<HTMLDivElement>(null);
 24	  useEffect(() => {
 25	    const previous = document.activeElement as HTMLElement | null;
 26	    const modal = ref.current;
 27	    modal?.querySelector<HTMLElement>("input,button,select")?.focus();
 28	    const key = (event: KeyboardEvent) => {
 29	      if (event.key === "Escape") onClose();
 30	      if (event.key === "Tab" && modal) {
 31	        const items = [...modal.querySelectorAll<HTMLElement>("button,input,select,[tabindex]:not([tabindex='-1'])")];
 32	        if (!items.length) return;
 33	        const first = items[0], last = items[items.length - 1];
 34	        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
 35	        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
 36	      }
 37	    };
 38	    document.addEventListener("keydown", key);
 39	    return () => { document.removeEventListener("keydown", key); previous?.focus(); };
 40	  }, [onClose]);
 41	  return <div className="modal-backdrop" role="presentation" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-head"><div><span className="eyebrow">GRID MODULE</span><h2 id="modal-title">{title}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Tutup dialog"><X /></button></div>{children}</div></div>;
 42	}
 43	
 44	function InstrumentSearch({ onClose, onAdd, initial }: { onClose: () => void; onAdd: (instrument: Instrument, timeframe: Timeframe) => Promise<void>; initial?: Panel }) {
 45	  const [query, setQuery] = useState(initial?.symbol.split(":")[1] ?? "");
 46	  const [results, setResults] = useState<Instrument[]>(INSTRUMENTS);
 47	  const [selected, setSelected] = useState<Instrument | null>(initial ? INSTRUMENTS.find((i) => i.symbol === initial.symbol) ?? null : null);
 48	  const [timeframe, setTimeframe] = useState<Timeframe>(initial?.timeframe ?? "1h");
 49	  const [busy, setBusy] = useState(false);
 50	  const [failed, setFailed] = useState("");
 51	  useEffect(() => {
 52	    const controller = new AbortController();
 53	    const timer = window.setTimeout(() => api.instruments(query, controller.signal).then(setResults).catch((error: Error) => error.name !== "AbortError" && setFailed(error.message)), 220);
 54	    return () => { clearTimeout(timer); controller.abort(); };
 55	  }, [query]);
 56	  const submit = async () => {
 57	    if (!selected) return;
 58	    setBusy(true); setFailed("");
 59	    try { await onAdd(selected, timeframe); onClose(); } catch (error) { setFailed(error instanceof Error ? error.message : "Gagal menyimpan."); setBusy(false); }
 60	  };
 61	  return <Modal title={initial ? "ATUR CHART" : "TAMBAH INSTRUMEN"} onClose={onClose}>
 62	    <label className="field-label" htmlFor="instrument-query">Cari exchange, pair, atau simbol</label>
 63	    <div className="search-box"><Search /><input id="instrument-query" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Contoh: BTC, Binance, ETHUSD" /></div>
 64	    <div className="instrument-list" role="listbox" aria-label="Hasil instrumen">
 65	      {results.map((item) => <button key={item.symbol} role="option" aria-selected={selected?.symbol === item.symbol} className={`instrument-row ${selected?.symbol === item.symbol ? "selected" : ""}`} onClick={() => setSelected(item)}><span className={`provider-mark ${item.provider.toLowerCase()}`}>{item.base.slice(0, 1)}</span><span><strong>{item.base}<i> / {item.quote}</i></strong><small>{item.provider} · {item.label}</small></span>{selected?.symbol === item.symbol && <Check />}</button>)}
 66	      {!results.length && <div className="no-results"><Search /><strong>Tidak ditemukan</strong><span>Coba kata kunci atau exchange lain.</span></div>}
 67	    </div>
 68	    <label className="field-label" htmlFor="add-timeframe">Timeframe awal</label>
 69	    <select id="add-timeframe" className="select-wide" value={timeframe} onChange={(e) => setTimeframe(e.target.value as Timeframe)}>{TIMEFRAMES.map((tf) => <option key={tf}>{tf}</option>)}</select>
 70	    {failed && <p className="form-error"><AlertTriangle />{failed}</p>}
 71	    <div className="modal-actions"><button className="btn ghost" onClick={onClose}>BATAL</button><button className="btn primary" disabled={!selected || busy} onClick={submit}>{busy ? <LoaderCircle className="spin" /> : <Plus />}{initial ? "SIMPAN" : "TAMBAH CHART"}</button></div>
 72	  </Modal>;
 73	}
 74	
 75	function ChartPanel({ panel, snapshot, onTimeframe, onRemove, onMove, onEdit, draggable, onDragStart, onDrop }: { panel: Panel; snapshot?: MarketSnapshot; onTimeframe: (tf: Timeframe) => void; onRemove: () => void; onMove: (direction: -1 | 1) => void; onEdit: () => void; draggable: boolean; onDragStart: () => void; onDrop: () => void }) {
 76	  const [retryKey, setRetryKey] = useState(0);
 77	  const pair = panel.symbol.split(":")[1];
 78	  const change = snapshot?.change24h;
 79	  return <article className="market-panel" draggable={draggable} onDragStart={onDragStart} onDragOver={(e) => e.preventDefault()} onDrop={onDrop}>
 80	    <header className="panel-head">
 81	      <button className="drag-handle" aria-label={`Seret ${panel.symbol}`} title="Seret untuk menyusun"><GripVertical /></button>
 82	      <div className="asset-icon">{pair?.slice(0, 1)}</div>
 83	      <div className="asset-title"><span>{panel.provider}</span><h2>{pair}</h2></div>
 84	      <div className="price-block"><strong>{snapshot?.price == null ? "—" : panel.symbol === "CRYPTOCAP:BTC.D" ? `${snapshot.price.toFixed(2)}%` : `$${money.format(snapshot.price)}`}</strong><span className={change == null ? "muted" : change >= 0 ? "positive" : "negative"}>{change == null ? "DATA TERTUNDA" : `${change >= 0 ? "+" : ""}${change.toFixed(2)}%`}</span></div>
 85	      <div className="panel-actions"><button className="icon-btn" onClick={() => onMove(-1)} aria-label="Pindah ke atas"><ArrowUp /></button><button className="icon-btn" onClick={() => onMove(1)} aria-label="Pindah ke bawah"><ArrowDown /></button><button className="icon-btn" onClick={onEdit} aria-label={`Atur ${panel.symbol}`}><Settings2 /></button><button className="icon-btn danger" onClick={onRemove} aria-label={`Hapus ${panel.symbol}`}><Trash2 /></button></div>
 86	    </header>
 87	    <div className="panel-meta"><div className="timeframes" aria-label={`Timeframe ${panel.symbol}`}>{TIMEFRAMES.map((tf) => <button key={tf} className={panel.timeframe === tf ? "active" : ""} onClick={() => onTimeframe(tf)}>{tf}</button>)}</div><span className="volume">VOL 24H&nbsp; {snapshot?.volume24h == null ? "—" : compact.format(snapshot.volume24h)}</span></div>
 88	    <div className="chart-wrap"><TradingViewChart panel={panel} retryKey={retryKey} />{snapshot?.sourceStatus === "unavailable" && <div className="data-warning"><AlertTriangle />Feed harga belum tersedia <button onClick={() => setRetryKey((v) => v + 1)}><RefreshCw /> Coba chart</button></div>}</div>
 89	  </article>;
 90	}
 91	
 92	function App() {
 93	  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
 94	  const [snapshots, setSnapshots] = useState<Record<string, MarketSnapshot>>({});
 95	  const [status, setStatus] = useState<ConnectionStatus>("connecting");
 96	  const [loadingError, setLoadingError] = useState("");
 97	  const [modal, setModal] = useState<"add" | "edit" | "delete" | null>(null);
 98	  const [activePanel, setActivePanel] = useState<Panel | null>(null);
 99	  const [saving, setSaving] = useState(false);
100	  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
101	  const [streamKey, setStreamKey] = useState(0);
102	  const [dragged, setDragged] = useState<string | null>(null);
103	  const [announcement, setAnnouncement] = useState("");
104	
105	  const load = useCallback(() => { setLoadingError(""); api.dashboard().then(setDashboard).catch((error: Error) => setLoadingError(error.message)); }, []);
106	  useEffect(load, [load]);
107	  const symbols = useMemo(() => [...new Set(dashboard?.panels.map((p) => p.symbol) ?? [])], [dashboard]);
108	  useEffect(() => {
109	    if (!symbols.length) { setStatus("offline"); return; }
110	    let closed = false, attempts = 0, socket: WebSocket | null = null, timer = 0;
111	    const connect = () => {
112	      if (closed) return;
113	      setStatus(attempts ? "reconnecting" : "connecting");
114	      socket = new WebSocket(`${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/api/market/stream`);
115	      socket.onopen = () => { attempts = 0; socket?.send(JSON.stringify({ type: "subscribe", symbols })); };
116	      socket.onmessage = (event) => {
117	        const message = JSON.parse(String(event.data)) as { type: string; status?: ConnectionStatus; data?: MarketSnapshot[] };
118	        if (message.status) setStatus(message.status);
119	        if (message.data) { setSnapshots((current) => ({ ...current, ...Object.fromEntries(message.data!.map((item) => [item.symbol, item])) })); setLastUpdate(Date.now()); }
120	      };
121	      socket.onerror = () => setStatus("degraded");
