 20	async function owner(request: Request): Promise<{ token: string; hash: string; cookie?: string }> {
 21	  const found = request.headers.get("cookie")?.match(/(?:^|;\s*)dmg_owner=([^;]+)/)?.[1];
 22	  const token = found ?? crypto.randomUUID().replaceAll("-", "") + crypto.randomUUID().replaceAll("-", "");
 23	  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
 24	  const hash = [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
 25	  return { token, hash, cookie: found ? undefined : `dmg_owner=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=31536000` };
 26	}
