 67	async function marketSnapshot(symbol: string, env?: Env): Promise<MarketSnapshot> {
 68	  const unavailable = (): MarketSnapshot => ({ symbol, price: null, change24h: null, volume24h: null, timestamp: Date.now(), stale: true, sourceStatus: "unavailable" });
 69	  try {
 70	    if (symbol.startsWith("BINANCE:")) {
 71	      const pair = symbol.split(":")[1];
 72	      const response = await fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${pair}`, { cf: { cacheTtl: 0 } });
 73	      if (!response.ok) return unavailable();
 74	      const data = await response.json() as { lastPrice: string; priceChangePercent: string; quoteVolume: string; closeTime: number };
 75	      return { symbol, price: Number(data.lastPrice), change24h: Number(data.priceChangePercent), volume24h: Number(data.quoteVolume), timestamp: data.closeTime, stale: Date.now() - data.closeTime > 60_000, sourceStatus: "live" };
 76	    }
 77	    if (symbol.startsWith("BITFINEX:")) {
 78	      const pair = symbol.split(":")[1];
 79	      const response = await fetch(`https://api-pub.bitfinex.com/v2/ticker/t${pair}`, { cf: { cacheTtl: 0 } });
 80	      if (!response.ok) return unavailable();
 81	      const data = await response.json() as number[];
 82	      return { symbol, price: data[6] ?? null, change24h: (data[5] ?? 0) * 100, volume24h: data[7] ?? null, timestamp: Date.now(), stale: false, sourceStatus: "live" };
 83	    }
 84	    if (env?.GLOBAL_METRICS_API_URL) {
 85	      const response = await fetch(`${env.GLOBAL_METRICS_API_URL}?symbol=${encodeURIComponent(symbol)}`, { headers: env.GLOBAL_METRICS_API_KEY ? { authorization: `Bearer ${env.GLOBAL_METRICS_API_KEY}` } : undefined });
 86	      if (response.ok) {
 87	        const data = await response.json() as { price: number; change24h?: number; timestamp?: number };
 88	        return { symbol, price: data.price, change24h: data.change24h ?? null, volume24h: null, timestamp: data.timestamp ?? Date.now(), stale: false, sourceStatus: "live" };
 89	      }
 90	    }
 91	    return unavailable();
 92	  } catch { return unavailable(); }
 93	}
