 95	export class MarketHub implements DurableObject {
 96	  constructor(private readonly state: DurableObjectState, private readonly env: Env) {}
 97	
 98	  async fetch(request: Request): Promise<Response> {
 99	    if (request.headers.get("upgrade") !== "websocket") return error("WebSocket diperlukan.", 426);
100	    const pair = new WebSocketPair();
101	    const client = pair[0];
102	    const server = pair[1];
103	    this.state.acceptWebSocket(server);
104	    server.serializeAttachment({ symbols: [] });
105	    server.send(JSON.stringify({ type: "status", status: "connecting" }));
106	    await this.state.storage.setAlarm(Date.now() + 250);
107	    return new Response(null, { status: 101, webSocket: client });
108	  }
109	
110	  async webSocketMessage(socket: WebSocket, message: string | ArrayBuffer) {
111	    if (typeof message !== "string" || message.length > 4096) return socket.close(1009, "Pesan terlalu besar");
112	    try {
113	      const parsed = JSON.parse(message) as { type?: string; symbols?: unknown };
114	      if (parsed.type === "ping") return socket.send(JSON.stringify({ type: "pong" }));
115	      if (parsed.type === "subscribe" && Array.isArray(parsed.symbols)) {
116	        const symbols = [...new Set(parsed.symbols.filter((value): value is string => typeof value === "string" && INSTRUMENTS.some((item) => item.symbol === value)))].slice(0, MAX_PANELS);
117	        socket.serializeAttachment({ symbols });
118	        const data = await Promise.all(symbols.map((symbol) => marketSnapshot(symbol, this.env)));
119	        socket.send(JSON.stringify({ type: "snapshot", data }));
120	        socket.send(JSON.stringify({ type: "status", status: data.some((item) => item.sourceStatus === "live") ? "live" : "degraded" }));
121	        await this.state.storage.setAlarm(Date.now() + 8_000);
122	      }
123	    } catch { socket.send(JSON.stringify({ type: "status", status: "degraded", message: "Pesan stream tidak valid." })); }
124	  }
125	
126	  async alarm() {
127	    const sockets = this.state.getWebSockets();
128	    if (!sockets.length) return;
129	    const all = new Set<string>();
130	    for (const socket of sockets) {
131	      const attachment = socket.deserializeAttachment() as { symbols?: string[] } | null;
132	      attachment?.symbols?.forEach((symbol) => all.add(symbol));
133	    }
134	    const snapshots = await Promise.all([...all].map((symbol) => marketSnapshot(symbol, this.env)));
135	    for (const socket of sockets) {
136	      const attachment = socket.deserializeAttachment() as { symbols?: string[] } | null;
137	      const subscribed = new Set(attachment?.symbols ?? []);
138	      socket.send(JSON.stringify({ type: "tick", data: snapshots.filter((item) => subscribed.has(item.symbol)) }));
139	    }
140	    await this.state.storage.setAlarm(Date.now() + 8_000);
141	  }
142	}
