144	export default {
145	  async fetch(request, env) {
146	    const url = new URL(request.url);
147	    const securityHeaders = { "cache-control": "no-store", "x-content-type-options": "nosniff" };
148	    if (url.pathname === "/api/health") {
149	      try { await env.DB.prepare("SELECT 1").first(); return json({ ok: true, database: "available", feed: "available" }, 200, securityHeaders); }
150	      catch { return json({ ok: false, database: "unavailable", feed: "available" }, 503, securityHeaders); }
151	    }
152	    if (url.pathname === "/api/instruments" && request.method === "GET") {
153	      const query = (url.searchParams.get("q") ?? "").trim().toLowerCase().slice(0, 60);
154	      const results = INSTRUMENTS.filter((item) => `${item.symbol} ${item.label} ${item.base} ${item.quote}`.toLowerCase().includes(query)).slice(0, 12);
155	      return json(results, 200, securityHeaders);
156	    }
157	    if (url.pathname === "/api/market/snapshot" && request.method === "GET") {
158	      const symbols = [...new Set((url.searchParams.get("symbols") ?? "").split(","))].filter((symbol) => INSTRUMENTS.some((item) => item.symbol === symbol)).slice(0, MAX_PANELS);
159	      return json(await Promise.all(symbols.map((symbol) => marketSnapshot(symbol, env))), 200, securityHeaders);
160	    }
161	    if (url.pathname === "/api/market/stream") {
162	      const id = env.MARKET_HUB.idFromName("global-market-hub");
163	      return env.MARKET_HUB.get(id).fetch(request);
164	    }
165	    if (!url.pathname.startsWith("/api/dashboard")) return error("Endpoint tidak ditemukan.", 404);
166	
167	    const identity = await owner(request);
168	    const headers = new Headers(securityHeaders);
169	    if (identity.cookie) headers.set("set-cookie", identity.cookie);
170	    try {
171	      if (url.pathname === "/api/dashboard" && request.method === "GET") return json(await fullDashboard(env, identity.hash), 200, headers);
172	      const dashboard = await ensureDashboard(env, identity.hash);
173	      const db = getDb(env);
174	      if (url.pathname === "/api/dashboard/layout" && request.method === "PUT") {
175	        const body = await parseBody(request);
176	        const columns = body?.columns;
177	        const panelIds = body?.panelIds;
178	        const owned = await db.select({ id: chartPanels.id }).from(chartPanels).where(eq(chartPanels.dashboardId, dashboard.id));
179	        if (!Number.isInteger(columns) || Number(columns) < 1 || Number(columns) > 4 || !Array.isArray(panelIds) || panelIds.length !== owned.length || new Set(panelIds).size !== panelIds.length || panelIds.some((id) => typeof id !== "string" || !owned.some((row) => row.id === id))) return error("Susunan dashboard tidak valid.", 422);
180	        await env.DB.batch([
181	          env.DB.prepare("UPDATE dashboards SET columns = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?").bind(columns, dashboard.id),
182	          ...panelIds.map((id, index) => env.DB.prepare("UPDATE chart_panels SET position = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND dashboard_id = ?").bind(index, id, dashboard.id)),
183	        ]);
184	        return json({ ok: true }, 200, headers);
185	      }
186	      if (url.pathname === "/api/dashboard/panels" && request.method === "POST") {
187	        const body = await parseBody(request);
188	        const instrument = validInstrument(body?.provider, body?.symbol);
189	        if (!instrument || !validTimeframe(body?.timeframe)) return error("Instrumen atau timeframe tidak valid.", 422);
190	        const rows = await db.select().from(chartPanels).where(eq(chartPanels.dashboardId, dashboard.id));
191	        if (rows.length >= MAX_PANELS) return error("Maksimum 16 chart.", 429);
192	        const row = { id: crypto.randomUUID(), dashboardId: dashboard.id, provider: instrument.provider, symbol: instrument.symbol, timeframe: body.timeframe, position: rows.length, span: 1 };
193	        await db.insert(chartPanels).values(row);
194	        return json(panelResponse({ ...row, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }), 201, headers);
195	      }
196	      const match = url.pathname.match(/^\/api\/dashboard\/panels\/([\w-]+)$/);
197	      if (match) {
198	        const panelId = match[1];
199	        const current = (await db.select().from(chartPanels).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id))).limit(1))[0];
200	        if (!current) return error("Panel tidak ditemukan.", 404);
201	        if (request.method === "DELETE") {
202	          await db.delete(chartPanels).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id)));
203	          return json({ ok: true }, 200, headers);
204	        }
205	        if (request.method === "PATCH") {
206	          const body = await parseBody(request);
207	          const provider = body?.provider ?? current.provider;
208	          const symbol = body?.symbol ?? current.symbol;
209	          const timeframe = body?.timeframe ?? current.timeframe;
210	          const span = body?.span ?? current.span;
211	          if (!validInstrument(provider, symbol) || !validTimeframe(timeframe) || !Number.isInteger(span) || Number(span) < 1 || Number(span) > 2) return error("Perubahan panel tidak valid.", 422);
212	          await db.update(chartPanels).set({ provider: String(provider), symbol: String(symbol), timeframe, span: Number(span), updatedAt: new Date().toISOString() }).where(and(eq(chartPanels.id, panelId), eq(chartPanels.dashboardId, dashboard.id)));
213	          const updated = (await db.select().from(chartPanels).where(eq(chartPanels.id, panelId)).limit(1))[0];
214	          return json(panelResponse(updated), 200, headers);
215	        }
216	      }
217	      return error("Endpoint tidak ditemukan.", 404);
218	    } catch (cause) {
219	      console.error("Dashboard request failed", cause);
220	      return error("Layanan dashboard sedang bermasalah. Coba lagi.", 500);
221	    }
222	  },
223	} satisfies ExportedHandler<Env>;
