    <label className="field-label" htmlFor="add-timeframe">Timeframe awal</label>
    <select id="add-timeframe" className="select-wide" value={timeframe} onChange={(e) => setTimeframe(e.target.value as Timeframe)}>{TIMEFRAMES.map((tf) => <option key={tf}>{tf}</option>)}</select>
    {failed && <p className="form-error"><AlertTriangle />{failed}</p>}
    <div className="modal-actions"><button className="btn ghost" onClick={onClose}>BATAL</button><button className="btn primary" disabled={!selected || busy} onClick={submit}>{busy ? <LoaderCircle className="spin" /> : <Plus />}{initial ? "SIMPAN" : "TAMBAH CHART"}</button></div>
  </Modal>;
}

