  8	const intervalMap: Record<Timeframe, string> = { "1m": "1", "5m": "5", "15m": "15", "1h": "60", "4h": "240", "1D": "D", "1W": "W" };
  9	const money = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
 10	const compact = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 2 });
 11	const instrumentBySymbol = new Map(INSTRUMENTS.map((instrument) => [instrument.symbol, instrument]));
 12	
 13	function AssetLogo({ instrument, symbol, size = "normal" }: { instrument?: Instrument; symbol: string; size?: "normal" | "large" }) {
 14	  const [failed, setFailed] = useState(false);
 15	  const rawAsset = instrument?.base ?? symbol.split(":")[1] ?? "?";
 16	  const fallback = rawAsset.replace(/[^A-Z0-9]/gi, "").slice(0, 2).toUpperCase() || "?";
 17	  const logoUrl = instrument?.logo ? `https://cdn.jsdelivr.net/npm/cryptocurrency-icons@0.18.1/svg/color/${instrument.logo}.svg` : null;
 18	  useEffect(() => setFailed(false), [logoUrl]);
 19	  return <span className={`asset-logo ${size === "large" ? "large" : ""} ${failed || !logoUrl ? "fallback" : ""}`} aria-hidden="true">
 20	    {logoUrl && !failed ? <img src={logoUrl} alt="" loading="lazy" onError={() => setFailed(true)} /> : <span>{fallback}</span>}
 21	  </span>;
 22	}
 23	
 24	function TradingViewChart({ panel, retryKey }: { panel: Panel; retryKey: number }) {
 25	  const src = `https://s.tradingview.com/widgetembed/?symbol=${encodeURIComponent(panel.symbol)}&interval=${intervalMap[panel.timeframe]}&theme=dark&style=1&locale=id&hide_side_toolbar=1&allow_symbol_change=0&save_image=0&calendar=0&utm_source=defi-market-grid`;
 26	  return <iframe key={`${panel.symbol}-${panel.timeframe}-${retryKey}`} className="chart-frame" title={`Chart ${panel.symbol}`} src={src} loading="lazy" allowFullScreen />;
 27	}
 28	
 29	function ConnectionBadge({ status, onRetry }: { status: ConnectionStatus; onRetry: () => void }) {
 30	  const labels: Record<ConnectionStatus, string> = { connecting: "MENGHUBUNGKAN", live: "LIVE", reconnecting: "MENYAMBUNG ULANG", degraded: "TERBATAS", offline: "OFFLINE" };
 31	  return <button className={`connection ${status}`} onClick={onRetry} title="Klik untuk sambungkan ulang"><span className="pulse" />{labels[status]}</button>;
 32	}
 33	
 34	function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
 35	  const ref = useRef<HTMLDivElement>(null);
 36	  useEffect(() => {
 37	    const previous = document.activeElement as HTMLElement | null;
 38	    const modal = ref.current;
 39	    modal?.querySelector<HTMLElement>("input,button,select")?.focus();
 40	    const key = (event: KeyboardEvent) => {
 41	      if (event.key === "Escape") onClose();
 42	      if (event.key === "Tab" && modal) {
 43	        const items = [...modal.querySelectorAll<HTMLElement>("button,input,select,[tabindex]:not([tabindex='-1'])")];
 44	        if (!items.length) return;
 45	        const first = items[0], last = items[items.length - 1];
 46	        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
 47	        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
 48	      }
 49	    };
 50	    document.addEventListener("keydown", key);
 51	    return () => { document.removeEventListener("keydown", key); previous?.focus(); };
 52	  }, [onClose]);
 53	  return <div className="modal-backdrop" role="presentation" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-head"><div><span className="eyebrow">GRID MODULE</span><h2 id="modal-title">{title}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Tutup dialog"><X /></button></div>{children}</div></div>;
 54	}
 55	
 56	function InstrumentSearch({ onClose, onAdd, initial }: { onClose: () => void; onAdd: (instrument: Instrument, timeframe: Timeframe) => Promise<void>; initial?: Panel }) {
 57	  const [query, setQuery] = useState(initial?.symbol.split(":")[1] ?? "");
 58	  const [results, setResults] = useState<Instrument[]>(INSTRUMENTS);
 59	  const [selected, setSelected] = useState<Instrument | null>(initial ? instrumentBySymbol.get(initial.symbol) ?? null : null);
 60	  const [timeframe, setTimeframe] = useState<Timeframe>(initial?.timeframe ?? "1h");
 61	  const [busySymbol, setBusySymbol] = useState<string | null>(null);
 62	  const [loading, setLoading] = useState(false);
 63	  const [failed, setFailed] = useState("");
 64	  useEffect(() => {
 65	    const controller = new AbortController();
 66	    setLoading(true); setFailed("");
 67	    const timer = window.setTimeout(() => api.instruments(query, controller.signal).then(setResults).catch((error: Error) => error.name !== "AbortError" && setFailed(error.message)).finally(() => setLoading(false)), 220);
 68	    return () => { clearTimeout(timer); controller.abort(); };
 69	  }, [query]);
 70	  const add = async (instrument: Instrument) => {
 71	    setBusySymbol(instrument.symbol); setFailed("");
 72	    try { await onAdd(instrument, timeframe); onClose(); }
 73	    catch (error) { setFailed(error instanceof Error ? error.message : "Gagal menyimpan."); setBusySymbol(null); }
 74	  };
 75	  return <Modal title={initial ? "ATUR CHART" : "TAMBAH CHART"} onClose={onClose}>
 76	    {!initial && <p className="catalog-intro">Katalog pair TradingView-compatible. Pilih timeframe, lalu tambahkan dalam sekali klik.</p>}
 77	    <div className="catalog-tools">
 78	      <div><label className="field-label" htmlFor="instrument-query">Cari coin, pair, atau exchange</label><div className="search-box"><Search /><input id="instrument-query" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="BTC, ETHUSDT, Binance…" /><span className="result-count">{loading ? "…" : results.length}</span></div></div>
 79	      <div className="timeframe-field"><label className="field-label" htmlFor="add-timeframe">Timeframe</label><select id="add-timeframe" className="select-wide" value={timeframe} onChange={(e) => setTimeframe(e.target.value as Timeframe)}>{TIMEFRAMES.map((tf) => <option key={tf}>{tf}</option>)}</select></div>
 80	    </div>
 81	    <div className="catalog-label"><span>INSTRUMEN TERSEDIA</span><span>SIMBOL / EXCHANGE</span></div>
 82	    <div className="instrument-list catalog" role="listbox" aria-label="Katalog instrumen">
 83	      {results.map((item) => <div key={item.symbol} className={`instrument-row ${selected?.symbol === item.symbol ? "selected" : ""}`}>
 84	        <button className="instrument-select" role="option" aria-selected={selected?.symbol === item.symbol} onClick={() => initial ? setSelected(item) : void add(item)} disabled={busySymbol !== null}>
 85	          <AssetLogo instrument={item} symbol={item.symbol} />
 86	          <span className="instrument-copy"><strong>{item.base}<i> / {item.quote}</i></strong><small>{item.label}</small><em>{item.symbol}</em></span>
 87	          <span className={`exchange-tag ${item.provider.toLowerCase()}`}>{item.provider}</span>
 88	        </button>
 89	        {!initial && <button className="quick-add" aria-label={`Tambahkan ${item.symbol}`} title="Tambah chart" onClick={() => void add(item)} disabled={busySymbol !== null}>{busySymbol === item.symbol ? <LoaderCircle className="spin" /> : <Plus />}</button>}
 90	        {initial && selected?.symbol === item.symbol && <Check className="selected-check" />}
 91	      </div>)}
 92	      {!loading && !results.length && <div className="no-results"><Search /><strong>Tidak ditemukan</strong><span>Coba simbol, nama coin, atau exchange lain.</span></div>}
 93	    </div>
 94	    {failed && <p className="form-error"><AlertTriangle />{failed}</p>}
 95	    {initial && <div className="modal-actions"><button className="btn ghost" onClick={onClose}>BATAL</button><button className="btn primary" disabled={!selected || busySymbol !== null} onClick={() => selected && void add(selected)}>{busySymbol ? <LoaderCircle className="spin" /> : <Check />} SIMPAN</button></div>}
 96	  </Modal>;
 97	}
 98	
 99	function ChartPanel({ panel, snapshot, onTimeframe, onRemove, onMove, onEdit, draggable, onDragStart, onDrop }: { panel: Panel; snapshot?: MarketSnapshot; onTimeframe: (tf: Timeframe) => void; onRemove: () => void; onMove: (direction: -1 | 1) => void; onEdit: () => void; draggable: boolean; onDragStart: () => void; onDrop: () => void }) {
100	  const [retryKey, setRetryKey] = useState(0);
101	  const pair = panel.symbol.split(":")[1];
102	  const instrument = instrumentBySymbol.get(panel.symbol);
103	  const change = snapshot?.change24h;
104	  return <article className="market-panel" draggable={draggable} onDragStart={onDragStart} onDragOver={(e) => e.preventDefault()} onDrop={onDrop}>
105	    <header className="panel-head">
106	      <button className="drag-handle" aria-label={`Seret ${panel.symbol}`} title="Seret untuk menyusun"><GripVertical /></button>
107	      <AssetLogo instrument={instrument} symbol={panel.symbol} />
108	      <div className="asset-title"><span>{panel.provider}</span><h2>{pair}</h2></div>
109	      <div className="price-block"><strong>{snapshot?.price == null ? "—" : instrument?.quote === "%" ? `${snapshot.price.toFixed(2)}%` : `${money.format(snapshot.price)}`}</strong><span className={change == null ? "muted" : change >= 0 ? "positive" : "negative"}>{change == null ? "DATA TERTUNDA" : `${change >= 0 ? "+" : ""}${change.toFixed(2)}%`}</span></div>
110	      <div className="panel-actions"><button className="icon-btn" onClick={() => onMove(-1)} aria-label="Pindah ke atas"><ArrowUp /></button><button className="icon-btn" onClick={() => onMove(1)} aria-label="Pindah ke bawah"><ArrowDown /></button><button className="icon-btn" onClick={onEdit} aria-label={`Atur ${panel.symbol}`}><Settings2 /></button><button className="icon-btn danger" onClick={onRemove} aria-label={`Hapus ${panel.symbol}`}><Trash2 /></button></div>
111	    </header>
112	    <div className="panel-meta"><div className="timeframes" aria-label={`Timeframe ${panel.symbol}`}>{TIMEFRAMES.map((tf) => <button key={tf} className={panel.timeframe === tf ? "active" : ""} onClick={() => onTimeframe(tf)}>{tf}</button>)}</div><span className="volume">VOL 24H&nbsp; {snapshot?.volume24h == null ? "—" : compact.format(snapshot.volume24h)}</span></div>
113	    <div className="chart-wrap"><TradingViewChart panel={panel} retryKey={retryKey} />{snapshot?.sourceStatus === "unavailable" && <div className="data-warning"><AlertTriangle />Feed harga belum tersedia <button onClick={() => setRetryKey((v) => v + 1)}><RefreshCw /> Coba chart</button></div>}</div>
114	  </article>;
115	}
116	
117	function App() {
118	  const [dashboard, setDashboard] = useState<Dashboard | null>(null);
119	  const [snapshots, setSnapshots] = useState<Record<string, MarketSnapshot>>({});
120	  const [status, setStatus] = useState<ConnectionStatus>("connecting");
121	  const [loadingError, setLoadingError] = useState("");
122	  const [modal, setModal] = useState<"add" | "edit" | "delete" | null>(null);
123	  const [activePanel, setActivePanel] = useState<Panel | null>(null);
124	  const [saving, setSaving] = useState(false);
125	  const [lastUpdate, setLastUpdate] = useState<number | null>(null);
126	  const [streamKey, setStreamKey] = useState(0);
127	  const [dragged, setDragged] = useState<string | null>(null);
128	  const [announcement, setAnnouncement] = useState("");
129	
130	  const load = useCallback(() => { setLoadingError(""); api.dashboard().then(setDashboard).catch((error: Error) => setLoadingError(error.message)); }, []);
131	  useEffect(load, [load]);
132	  const symbols = useMemo(() => [...new Set(dashboard?.panels.map((p) => p.symbol) ?? [])], [dashboard]);
133	  useEffect(() => {
134	    if (!symbols.length) { setStatus("offline"); return; }
135	    let closed = false, attempts = 0, socket: WebSocket | null = null, timer = 0;
136	    const connect = () => {
137	      if (closed) return;
138	      setStatus(attempts ? "reconnecting" : "connecting");
139	      socket = new WebSocket(`${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/api/market/stream`);
140	      socket.onopen = () => { attempts = 0; socket?.send(JSON.stringify({ type: "subscribe", symbols })); };
141	      socket.onmessage = (event) => {
142	        const message = JSON.parse(String(event.data)) as { type: string; status?: ConnectionStatus; data?: MarketSnapshot[] };
143	        if (message.status) setStatus(message.status);
144	        if (message.data) { setSnapshots((current) => ({ ...current, ...Object.fromEntries(message.data!.map((item) => [item.symbol, item])) })); setLastUpdate(Date.now()); }
145	      };
146	      socket.onerror = () => setStatus("degraded");
147	      socket.onclose = () => { if (!closed) { attempts++; setStatus("reconnecting"); timer = window.setTimeout(connect, Math.min(30_000, 1000 * 2 ** attempts) + Math.random() * 500); } };
148	    };
149	    api.snapshots(symbols).then((data) => setSnapshots(Object.fromEntries(data.map((item) => [item.symbol, item])))).catch(() => undefined);
150	    connect();
151	    const heartbeat = window.setInterval(() => socket?.readyState === WebSocket.OPEN && socket.send(JSON.stringify({ type: "ping" })), 20_000);
152	    return () => { closed = true; clearTimeout(timer); clearInterval(heartbeat); socket?.close(); };
153	  }, [symbols, streamKey]);
154	
155	  const saveLayout = async (panels: Panel[], columns = dashboard?.columns ?? 2) => {
156	    if (!dashboard) return;
157	    const old = dashboard;
158	    const positioned = panels.map((panel, position) => ({ ...panel, position }));
159	    setDashboard({ ...dashboard, panels: positioned, columns }); setSaving(true);
160	    try { await api.saveLayout(columns, positioned.map((p) => p.id)); }
161	    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Gagal menyimpan susunan."); }
162	    finally { setSaving(false); }
163	  };
164	  const move = (id: string, direction: -1 | 1) => {
165	    if (!dashboard) return;
166	    const index = dashboard.panels.findIndex((p) => p.id === id), target = index + direction;
167	    if (target < 0 || target >= dashboard.panels.length) return;
168	    const next = [...dashboard.panels]; [next[index], next[target]] = [next[target], next[index]];
169	    setAnnouncement(`${dashboard.panels[index].symbol} dipindahkan ke posisi ${target + 1}.`); void saveLayout(next);
170	  };
171	  const mutatePanel = async (panel: Panel, changes: Partial<Panel>) => {
172	    if (!dashboard) return;
173	    const old = dashboard; setDashboard({ ...dashboard, panels: dashboard.panels.map((p) => p.id === panel.id ? { ...p, ...changes } : p) }); setSaving(true);
174	    try { const updated = await api.updatePanel(panel.id, changes); setDashboard((current) => current ? { ...current, panels: current.panels.map((p) => p.id === panel.id ? updated : p) } : current); }
175	    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Perubahan gagal."); throw error; }
176	    finally { setSaving(false); }
177	  };
178	  const remove = async () => {
179	    if (!dashboard || !activePanel) return; const old = dashboard; setModal(null); setDashboard({ ...dashboard, panels: dashboard.panels.filter((p) => p.id !== activePanel.id) }); setSaving(true);
180	    try { await api.removePanel(activePanel.id); setAnnouncement(`${activePanel.symbol} dihapus.`); }
181	    catch (error) { setDashboard(old); setAnnouncement(error instanceof Error ? error.message : "Gagal menghapus."); }
182	    finally { setSaving(false); setActivePanel(null); }
183	  };
184	
185	  if (loadingError) return <main className="center-state"><AlertTriangle /><h1>DASHBOARD TIDAK TERJANGKAU</h1><p>{loadingError}</p><button className="btn primary" onClick={load}><RefreshCw /> COBA LAGI</button></main>;
186	  if (!dashboard) return <main className="center-state"><LoaderCircle className="spin" /><h1>MENYUSUN MARKET GRID</h1><p>Memuat panel dan menghubungkan feed pasar…</p></main>;
187	
188	  return <div className="app-shell">
189	    <div className="ticker-strip"><span>DEFI MARKET GRID // LIVE INTELLIGENCE</span><span>BTC · ETH · SOL · XRP · DOGE · TOTAL MARKET</span><span>UTC {new Date().toISOString().slice(11, 19)}</span></div>
190	    <header className="topbar"><a className="brand" href="#top" aria-label="DeFi Market Grid"><span className="brand-mark"><BarChart3 /></span><span><strong>DEFI</strong> MARKET GRID<small>REAL-TIME CRYPTO MONITOR</small></span></a><div className="top-actions"><ConnectionBadge status={status} onRetry={() => setStreamKey((v) => v + 1)} /><span className="updated">UPDATE TERAKHIR<strong>{lastUpdate ? new Date(lastUpdate).toLocaleTimeString("id-ID") : "—"}</strong></span><button className="btn primary" onClick={() => setModal("add")}><Plus /> TAMBAH CHART</button></div></header>
191	    <main id="top"><section className="workspace-head"><div><span className="eyebrow">WORKSPACE / 01</span><h1>{dashboard.name}</h1><p>{dashboard.panels.length} MODUL AKTIF · MARKET DATA TANPA REFRESH</p></div><div className="layout-control"><label><LayoutGrid /> KOLOM</label>{[1, 2, 3, 4].map((count) => <button key={count} aria-label={`${count} kolom`} className={dashboard.columns === count ? "active" : ""} onClick={() => void saveLayout(dashboard.panels, count)}>{count}</button>)}<span className={saving ? "saving active" : "saving"}>{saving ? "MENYIMPAN…" : "TERSIMPAN"}</span></div></section>
192	      {dashboard.panels.length ? <section className="market-grid" style={{ "--columns": dashboard.columns } as React.CSSProperties}>{dashboard.panels.map((panel) => <ChartPanel key={panel.id} panel={panel} snapshot={snapshots[panel.symbol]} draggable onDragStart={() => setDragged(panel.id)} onDrop={() => { if (!dragged || dragged === panel.id) return; const next = [...dashboard.panels]; const from = next.findIndex((p) => p.id === dragged), to = next.findIndex((p) => p.id === panel.id); const [item] = next.splice(from, 1); next.splice(to, 0, item); setDragged(null); void saveLayout(next); }} onMove={(d) => move(panel.id, d)} onTimeframe={(tf) => void mutatePanel(panel, { timeframe: tf })} onEdit={() => { setActivePanel(panel); setModal("edit"); }} onRemove={() => { setActivePanel(panel); setModal("delete"); }} />)}</section> : <section className="empty-state"><Activity /><span className="eyebrow">GRID KOSONG</span><h2>MULAI PANTAU PASAR</h2><p>Tambahkan instrumen pertama untuk membangun workspace Anda.</p><button className="btn primary" onClick={() => setModal("add")}><Plus /> TAMBAH CHART</button></section>}
193	    </main>
194	    <footer><div><strong>DATA PIPELINE</strong><span><i className="dot live" /> BINANCE PUBLIC API</span><span><i className="dot live" /> BITFINEX PUBLIC API</span><span><i className="dot limited" /> GLOBAL METRICS*</span></div><p>Chart oleh <a href="https://www.tradingview.com/" target="_blank" rel="noreferrer">TradingView</a>. Data oleh <a href="https://www.binance.com/en/terms" target="_blank" rel="noreferrer">Binance</a> dan <a href="https://www.bitfinex.com/legal/" target="_blank" rel="noreferrer">Bitfinex</a>. Data hanya untuk informasi, bukan nasihat finansial.</p></footer>
195	    <p className="sr-only" aria-live="polite">{announcement}</p>
196	    {modal === "add" && <InstrumentSearch onClose={() => setModal(null)} onAdd={async (instrument, timeframe) => { const added = await api.addPanel(instrument.provider, instrument.symbol, timeframe); setDashboard((current) => current ? { ...current, panels: [...current.panels, added] } : current); setAnnouncement(`${instrument.symbol} ditambahkan.`); }} />}
197	    {modal === "edit" && activePanel && <InstrumentSearch initial={activePanel} onClose={() => setModal(null)} onAdd={async (instrument, timeframe) => mutatePanel(activePanel, { provider: instrument.provider, symbol: instrument.symbol, timeframe })} />}
198	    {modal === "delete" && activePanel && <Modal title="HAPUS CHART?" onClose={() => setModal(null)}><div className="confirm-copy"><AssetLogo instrument={instrumentBySymbol.get(activePanel.symbol)} symbol={activePanel.symbol} size="large" /><p><strong>{activePanel.symbol}</strong> akan dihapus dari grid. Tindakan ini tidak dapat dibatalkan.</p></div><div className="modal-actions"><button className="btn ghost" onClick={() => setModal(null)}>BATAL</button><button className="btn destructive" onClick={() => void remove()}><Trash2 /> HAPUS</button></div></Modal>}
199	  </div>;
200	}
201	
202	createRoot(document.getElementById("root") as HTMLElement).render(<StrictMode><App /></StrictMode>);
