 99	function ChartPanel({ panel, snapshot, onTimeframe, onRemove, onMove, onEdit, draggable, onDragStart, onDrop }: { panel: Panel; snapshot?: MarketSnapshot; onTimeframe: (tf: Timeframe) => void; onRemove: () => void; onMove: (direction: -1 | 1) => void; onEdit: () => void; draggable: boolean; onDragStart: () => void; onDrop: () => void }) {
100	  const [retryKey, setRetryKey] = useState(0);
101	  const pair = panel.symbol.split(":")[1];
102	  const instrument = instrumentBySymbol.get(panel.symbol);
103	  const change = snapshot?.change24h;
104	  return <article className="market-panel" draggable={draggable} onDragStart={onDragStart} onDragOver={(e) => e.preventDefault()} onDrop={onDrop}>
105	    <header className="panel-head">
106	      <button className="drag-handle" aria-label={`Seret ${panel.symbol}`} title="Seret untuk menyusun"><GripVertical /></button>
107	      <AssetLogo instrument={instrument} symbol={panel.symbol} />
108	      <div className="asset-title"><span>{panel.provider}</span><h2>{pair}</h2></div>
109	      <div className="price-block"><strong>{snapshot?.price == null ? "—" : instrument?.quote === "%" ? `${snapshot.price.toFixed(2)}%` : `${money.format(snapshot.price)}`}</strong><span className={change == null ? "muted" : change >= 0 ? "positive" : "negative"}>{change == null ? "DATA TERTUNDA" : `${change >= 0 ? "+" : ""}${change.toFixed(2)}%`}</span></div>
110	      <div className="panel-actions"><button className="icon-btn" onClick={() => onMove(-1)} aria-label="Pindah ke atas"><ArrowUp /></button><button className="icon-btn" onClick={() => onMove(1)} aria-label="Pindah ke bawah"><ArrowDown /></button><button className="icon-btn" onClick={onEdit} aria-label={`Atur ${panel.symbol}`}><Settings2 /></button><button className="icon-btn danger" onClick={onRemove} aria-label={`Hapus ${panel.symbol}`}><Trash2 /></button></div>
111	    </header>
112	    <div className="panel-meta"><div className="timeframes" aria-label={`Timeframe ${panel.symbol}`}>{TIMEFRAMES.map((tf) => <button key={tf} className={panel.timeframe === tf ? "active" : ""} onClick={() => onTimeframe(tf)}>{tf}</button>)}</div><span className="volume">VOL 24H&nbsp; {snapshot?.volume24h == null ? "—" : compact.format(snapshot.volume24h)}</span></div>
