 3	async function request<T>(path: string, init?: RequestInit): Promise<T> {
 4	  const response = await fetch(path, init);
 5	  if (!response.ok) {
 6	    const body = await response.json().catch(() => ({ error: "Permintaan gagal." })) as { error?: string };
 7	    throw new Error(body.error ?? `Permintaan gagal (${response.status}).`);
 8	  }
 9	  return response.json() as Promise<T>;
10	}
