 37	    const previous = document.activeElement as HTMLElement | null;
 38	    const modal = ref.current;
 39	    modal?.querySelector<HTMLElement>("input,button,select")?.focus();
 40	    const key = (event: KeyboardEvent) => {
 41	      if (event.key === "Escape") onClose();
 42	      if (event.key === "Tab" && modal) {
 43	        const items = [...modal.querySelectorAll<HTMLElement>("button,input,select,[tabindex]:not([tabindex='-1'])")];
 44	        if (!items.length) return;
 45	        const first = items[0], last = items[items.length - 1];
 46	        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
 47	        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
 48	      }
 49	    };
 50	    document.addEventListener("keydown", key);
 51	    return () => { document.removeEventListener("keydown", key); previous?.focus(); };
 52	  }, [onClose]);
 53	  return <div className="modal-backdrop" role="presentation" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><div className="modal-head"><div><span className="eyebrow">GRID MODULE</span><h2 id="modal-title">{title}</h2></div><button className="icon-btn" onClick={onClose} aria-label="Tutup dialog"><X /></button></div>{children}</div></div>;
