195	      socket = new WebSocket(`${location.protocol === "https:" ? "wss:" : "ws:"}//${location.host}/api/market/stream`);
196	      socket.onopen = () => { attempts = 0; socket?.send(JSON.stringify({ type: "subscribe", symbols })); };
197	      socket.onmessage = (event) => {
