199	        if (message.status) setStatus(message.status);
200	        if (message.data) { setSnapshots((current) => ({ ...current, ...Object.fromEntries(message.data!.map((item) => [item.symbol, item])) })); setLastUpdate(Date.now()); }
201	      };
202	      socket.onerror = () => setStatus("degraded");
203	      socket.onclose = () => { if (!closed) { attempts++; setStatus("reconnecting"); timer = window.setTimeout(connect, Math.min(30_000, 1000 * 2 ** attempts) + Math.random() * 500); } };
204	    };
